SPECULATIVE STARTER:

const reverb = new Tone.Reverb({ decay: 8, wet: 0.8 }).toDestination();
const chorus = new Tone.Chorus(4, 2.5, 0.7).connect(reverb);

// Ethereal Lead Vocal
const leadSynth = new Tone.PolySynth(Tone.Synth, {
  oscillator: { type: 'fattriangle', count: 3, spread: 20 },
  envelope: { attack: 0.05, decay: 0.2, sustain: 0.8, release: 4 },
  filter: { type: 'lowpass', frequency: 3000, Q: 1 }
}).connect(chorus);
// lead melody example (from 'I'll leave it for you')
const leadMelody = ['B4', null, 'B4', 'A4', 'G4', null, 'E4', null];

// Vocal Choir Pad
const padSynth = new Tone.PolySynth(Tone.Synth, {
  oscillator: { type: 'fatsawtooth', count: 7, spread: 50 },
  envelope: { attack: 3, decay: 0.5, sustain: 1, release: 6 },
  volume: -12,
  filter: { type: 'lowpass', frequency: 1500, Q: 2 }
}).connect(chorus);
// pad chords example (Em -> Cmaj)
const padChords = [
  { time: '0:0', note: ['E4', 'G4', 'B4'] },
  { time: '1:0', note: ['C4', 'E4', 'G4'] }
];
